INSERT INTO `events` (`id`, `title`, `description`, `image_url`, `link_url`, `start_date`, `end_date`, `created_at`, `updated_at`, `status`, `display_order`) VALUES
(8, 'Ưu Đãi Mùa Hè - Giảm 50% Toàn Bộ', 'Tận hưởng ưu đãi lớn nhất mùa hè trên hàng ngàn sản phẩm chọn lọc. Đừng bỏ lỡ!', 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1753907766/Brown_and_White_Modern_Artisan_Furniture_and_Decor_Banner_1_lqgaaw.png', 'https://sonaspace.store/san-pham', '2025-07-01 00:00:00', '2031-07-23 23:59:59', '2025-07-28 18:46:28', '2025-08-24 17:48:42', 'active', 1),
(9, 'Flash Sale Hôm Nay - Giảm 30% Điện Tử', 'Chỉ diễn ra trong 24 giờ! Cơ hội vàng để sở hữu các thiết bị điện tử cao cấp với giá cực sốc.', 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1753938773/Neutral_Minimalist_Interior_Design_Banner_1_g55jkx.png', 'https://sonaspace.store/san-pham/sofa-amsterdam?color=19', '2025-07-28 00:00:00', '2034-07-24 23:59:59', '2025-07-28 18:46:28', '2025-08-24 17:48:59', 'active', 2),
(10, 'Chương Trình Khuyến Mãi Tháng 8', 'Sẵn sàng cho tháng 8 với vô vàn ưu đãi hấp dẫn từ các đối tác của chúng tôi.', 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1753733228/Neutral_Minimalist_Interior_Design_Banner_u1hjbd.png', 'https://sonaspace.timefortea.io.vn/san-pham', '2025-04-13 00:00:00', '2034-08-23 23:59:59', '2025-07-28 18:46:28', '2025-08-04 13:20:33', 'expired', 1),
(11, 'Sự Kiện Ra Mắt Sản Phẩm Mới', 'Đăng ký để nhận thông báo sớm nhất về sản phẩm đột phá sắp ra mắt.', 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1753907766/Brown_and_White_Modern_Artisan_Furniture_and_Decor_Banner_1_lqgaaw.png', 'https://sonaspace.timefortea.io.vn/san-pham', '2025-09-10 09:00:00', '2025-09-10 17:00:00', '2025-07-28 18:46:28', '2025-07-30 20:37:57', 'scheduled', 2),
(12, 'Ưu Đãi Đã Tạm Dừng', 'Chương trình này tạm thời không hoạt động do hết hàng. Vui lòng quay lại sau.', 'https://lipsum.app/random/1600x900', 'https://sonaspace.timefortea.io.vn/san-pham', '2025-07-15 00:00:00', '2025-08-15 23:59:59', '2025-07-28 18:46:28', '2025-08-04 13:20:37', 'expired', 3),
(14, 'Khai trương chi nhánh mới', 'Sự kiện khai trương chi nhánh mới tại TP.HCM.', 'https://res.cloudinary.com/demo/image/upload/v1690000000/event-banner.jpg', 'https://example.com/su-kien/khai-truong', '2025-08-10 00:00:00', '2025-08-20 00:00:00', '2025-08-04 14:01:28', '2025-08-16 01:16:56', 'expired', 1),
(15, 'xcc', 'adsfas', 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1754318821/SonaSpace/PopupAd/x3moef83uixrmlqr9sw5.jpg', 'dfasdfa', '2025-08-04 21:46:00', '2028-10-04 00:49:00', '2025-08-04 14:47:02', '2025-08-16 01:17:06', 'expired', 1);
INSERT INTO `materials` (`material_id`, `material_name`, `material_description`, `slug`, `material_priority`, `material_status`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'Gỗ tự nhiên', 'Gỗ tự nhiên là loại gỗ được khai thác trực tiếp từ rừng hoặc từ các loại cây trồng lâu năm, không qua quá trình ép công nghiệp. Với vân gỗ độc đáo, độ bền cao và khả năng chống mối mọt tốt, gỗ tự nhiên thường được sử dụng cho các sản phẩm nội thất cao cấp, mang lại vẻ đẹp sang trọng và giá trị sử dụng lâu dài.', 'go_tu_nhien', 1, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(2, 'Gỗ MDF', 'Gỗ MDF (Medium Density Fiberboard) là loại gỗ công nghiệp được tạo thành từ bột gỗ nghiền nhỏ, trộn keo và ép nén ở áp suất cao. MDF có bề mặt nhẵn, dễ sơn phủ, thi công nhanh và giá thành thấp hơn so với gỗ tự nhiên. Tuy không bền bằng gỗ thật nhưng vẫn là lựa chọn phổ biến cho nội thất gia đình và văn phòng.', 'go_mdf', 2, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(3, 'Gỗ công nghiệp', 'Gỗ công nghiệp là tên gọi chung của các loại gỗ được sản xuất từ nguyên liệu gỗ tái chế hoặc gỗ trồng ngắn ngày, qua xử lý ép dán thành tấm. Các loại gỗ công nghiệp phổ biến gồm MDF, MFC, HDF... Ưu điểm là giá rẻ, dễ thi công, thân thiện với môi trường và phù hợp cho sản phẩm sản xuất hàng loạt.', 'go_cong_nghiep', 3, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(4, 'Gỗ sồi', 'Gỗ sồi là loại gỗ nhập khẩu từ châu Âu hoặc Mỹ, nổi bật với màu sắc sáng, vân gỗ đẹp và khả năng chịu lực tốt. Gỗ sồi thường được sử dụng trong sản xuất bàn, ghế, tủ, kệ mang phong cách hiện đại hoặc tân cổ điển. Ngoài ra, gỗ sồi còn chống cong vênh và có độ bền theo thời gian.', 'go_soi', 4, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(5, 'Da thật', 'Da thật được làm từ da động vật như bò, dê, cừu..., trải qua quá trình xử lý thuộc da kỹ thuật cao để đảm bảo độ mềm, độ bền và tính thẩm mỹ. Ưu điểm là bề mặt mịn, thông thoáng, có mùi đặc trưng và càng sử dụng lâu càng bóng đẹp. Da thật thường được dùng cho sofa cao cấp, ghế văn phòng, túi xách thời trang...', 'da_that', 5, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(6, 'Da công nghiệp', 'Da công nghiệp (da PU, da Simili) là vật liệu tổng hợp mô phỏng da thật, được phủ nhựa PVC hoặc polyurethane trên nền vải. Có nhiều màu sắc, dễ vệ sinh, giá thành thấp hơn da thật và bền trong môi trường sử dụng thông thường. Phù hợp làm ghế sofa, bọc đệm, túi xách, giày dép phổ thông.', 'da_cong_nghiep', 6, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(7, 'Vải bố', 'Vải bố là loại vải dệt thô từ sợi cotton hoặc sợi tổng hợp, có độ dày cao và bề mặt sần nhẹ. Vải bố thường được dùng trong sản phẩm nội thất vintage, bohemian hoặc trang trí thủ công vì tạo cảm giác mộc mạc, bền bỉ. Ngoài ra, vải bố cũng thân thiện với môi trường và có khả năng hút ẩm tốt.', 'vai_bo', 7, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(8, 'Vải nỉ', 'Vải nỉ là loại vải dệt từ sợi tổng hợp hoặc tự nhiên, có lớp lông mịn bề mặt giúp giữ nhiệt tốt, tạo cảm giác ấm áp và mềm mại. Thường được dùng cho nội thất như sofa mùa lạnh, chăn mền, trang phục mùa đông và đồ trang trí vì đặc tính êm ái và đa dạng màu sắc.', 'vai_ni', 8, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(9, 'Lông thú tổng hợp', 'Lông thú tổng hợp là chất liệu giả lông động vật, được sản xuất từ sợi tổng hợp như polyester, acrylic. Ưu điểm là mềm, ấm, thân thiện với môi trường và không gây tổn hại đến động vật. Thường dùng trong chăn, áo khoác, gối trang trí hoặc các chi tiết sang trọng cho nội thất.', 'long_thu_tong_hop', 9, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(10, 'Pha lê', 'Pha lê là loại thủy tinh cao cấp có thành phần oxit chì giúp tăng độ trong suốt và độ sáng bóng. Chất liệu này thường được sử dụng cho các sản phẩm đèn trang trí, chân nến, lọ hoa hoặc các chi tiết trang trí tinh xảo, mang lại vẻ đẹp quý phái và sang trọng cho không gian.', 'pha_le', 10, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(11, 'Kim loại sơn tĩnh điện', 'Kim loại sơn tĩnh điện là kim loại (thường là sắt, thép) được phủ một lớp sơn bằng phương pháp tĩnh điện, giúp lớp sơn bám chắc, bền màu và chống gỉ sét hiệu quả. Được dùng rộng rãi trong nội thất hiện đại như bàn ghế, khung giường, kệ tủ, đảm bảo độ bền cao và thẩm mỹ lâu dài.', 'kim_loai_son_tinh_dien', 11, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(12, 'Nhựa ABS', 'Nhựa ABS (Acrylonitrile Butadiene Styrene) là loại nhựa kỹ thuật có độ cứng cao, chịu va đập tốt và bền với thời gian. ABS không mùi, an toàn và có khả năng chống ẩm, thường dùng cho vỏ máy, thiết bị gia dụng, đồ chơi, và đồ nội thất như ghế nhựa cao cấp.', 'nhua_abs', 12, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(13, 'Thủy tinh', 'Thủy tinh là chất liệu trong suốt, dễ tạo hình, bề mặt mịn và sạch sẽ. Được ứng dụng rộng rãi trong đồ dùng nhà bếp, đèn chiếu sáng, mặt bàn, hoặc các chi tiết trang trí nội thất hiện đại. Ưu điểm là không thấm nước, dễ lau chùi và tạo hiệu ứng ánh sáng tốt.', 'thuy_tinh', 13, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(14, 'Vải Canvas', 'Vải Canvas là loại vải dày, được dệt từ sợi cotton hoặc polyester, có độ bền và khả năng chịu lực tốt. Canvas thường được sử dụng cho balo, túi xách, tranh vẽ, ghế lười và các sản phẩm nội thất phong cách trẻ trung. Chất liệu này cũng dễ in ấn và có tuổi thọ cao.', 'vai_canvas', 14, 1, '2025-07-15 14:19:48', '2025-07-18 02:36:10', NULL),
(17, 'cadfdfaczvvzxcvzxc', 'fdà', 'cadfdfaczvvzxcvzxc', NULL, 0, '2025-07-18 19:46:09', '2025-08-21 00:39:59', NULL),
(19, 'àd', 'dfàd', 'ad', NULL, 0, '2025-07-18 19:48:06', '2025-08-21 00:40:41', NULL);
INSERT INTO `news` (`news_id`, `news_category_id`, `news_name`, `news_image`, `news_slug`, `news_title`, `news_description`, `news_content`, `news_priority`, `news_view`, `news_status`, `news_author`, `news_comment`, `news_reaction`, `updated_at`, `created_at`, `deleted_at`) VALUES
(46, 1, NULL, 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1753280779/9-1752072967_xx6djk.webp', 'dua-bep-vao-trung-tam-can-ho-61-m2-voi-200-trieu-dong', 'Đưa bếp vào trung tâm căn hộ 61 m2 với 200 triệu đồng', NULL, '<h1 class=\"title-detail\" style=\"text-align: center;\">Đưa bếp vào trung tâm căn hộ 61 m2 với 200 triệu đồng</h1>\n<p class=\"description\" style=\"text-align: center;\"><span class=\"location-stamp\">Hà Nội - </span>Bàn ăn cũng là bàn làm việc, đặt ngay gần cửa sổ, hướng tầm nhìn ra khung cảnh thành phố bên dưới.</p>\n<p class=\"description\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752660826/SonaSpace/News/us5jdkwzlsdwvubthqli.webp\" width=\"891\" height=\"594\"></p>\n<p class=\"Normal\">Căn hộ có diện tích 61 m2, tọa lạc tại một tòa chung cư thuộc Hà Nội.</p>\n<p class=\"Normal\" style=\"text-align: left;\">Dựa theo sở thích và mong muốn của gia chủ, nhóm KTS chọn phương án thiết kế các không gian theo hướng tối giản, không phô trương, không cố \"gồng\" để đẹp, nhưng mọi thứ đều gọn gàng, ấm cúng.</p>\n<p class=\"Normal\">Thay vì ưu tiên phòng khách như các căn hộ thông thường, phòng bếp được đặt ở trung tâm, sát ban công, luôn ngập tràn ánh sáng tự nhiên.</p>\n<p class=\"description\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752660826/SonaSpace/News/clzxorielj0xhpwhcxwh.webp\" width=\"745\" height=\"1118\"></p>\n<p class=\"Normal\">Bàn ăn cũng là bàn làm việc, đặt ngay gần cửa sổ ban công, hướng tầm nhìn rộng thoáng ra khoảng trời nhỏ.</p>\n<p class=\"Normal\">Nhờ thiết kế tối giản, căn hộ tạo cảm giác không có chi tiết nào bị thừa. Từ chiếc ghế có tay vịn bo cong, đến đệm cửa sổ dài... không quá nổi bật nhưng lại giúp người ở cảm thấy dễ chịu.</p>\n<p class=\"Normal\">Khi ở nhà, người lớn có thể vừa nấu ăn vừa trò chuyện. Trẻ nhỏ thoải mái chơi trong phòng, không phải né góc sắc cạnh hay lo ngại làm bẩn đồ dùng.</p>\n<p class=\"Normal\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752660827/SonaSpace/News/xx7tzwolhjwg95w5i2sz.webp\" width=\"756\" height=\"504\"></p>\n<p class=\"Normal\">Căn hộ chỉ có một mặt thoáng nhưng thông qua lớp rèm mỏng ở ban công, ánh sáng vẫn tràn đều khắp không gian sinh hoạt chung.</p>\n<p class=\"Normal\">Ghế sofa không to nhưng đủ sâu để gia chủ thoải mái ngồi đọc sách.</p>\n<p class=\"Normal\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752660828/SonaSpace/News/cikbgy1756qv4zakiqr7.webp\" width=\"1049\" height=\"749\"></p>\n<p class=\"Normal\">Thay vì bố trí nhiều đồ trang trí, nhóm thiết kế tạo điểm nhấn ở các chi tiết nhỏ trên đồ nội thất.</p>', 0, 69, 1, '5', '0', 0, '2025-08-22 22:10:32', '2025-07-16 17:13:49', NULL),
(49, 4, NULL, 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752787274/SonaSpace/News/News/jst8caktidfbgtfpg7rc.jpg', 'thac-mac-huong-nam-ngu-quay-dau-ra-cua-so-co-sao-khong', 'Thắc mắc: Hướng nằm ngủ quay đầu ra cửa sổ có sao không?', NULL, '<h1 class=\"sb-title-article\"><span style=\"font-size: 18pt; font-family: arial, helvetica, sans-serif;\">Thắc mắc: Hướng nằm ngủ quay đầu ra cửa sổ có sao không?</span></h1>\n<p><span style=\"font-size: 12pt; font-family: arial, helvetica, sans-serif;\">Vị trí&nbsp;<strong>nằm ngủ quay đầu ra cửa sổ có sao không</strong>?&nbsp;Giường ngủ nên đặt ở hướng nào? Đây là câu hỏi mà nhiều người thường băn khoăn khi sắp xếp không gian phòng ngủ.&nbsp;Việc bố trí giường ngủ không chỉ ảnh hưởng đến thẩm mỹ của căn phòng mà còn liên quan đến chất lượng giấc ngủ và sức khỏe của bạn.<strong> Sona Space </strong>sẽ giúp bạn hiểu về vấn đề này cũng như các thông tin về cách kê giường ngủ hợp lý nhé.</span></p>\n<h2 style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong><img src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752787271/SonaSpace/News/Content/jmzmc89hznqhb7k3mve0.jpg\"></strong></span></h2>\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Nằm ngủ quay đầu ra cửa sổ tức là kê đầu giường hoặc gối nằm hướng trực tiếp về phía cửa sổ</span></p>\n<h2 style=\"text-align: left;\"><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt;\">Vị trí nằm ngủ quay đầu ra cửa sổ có sao không?</span></h2>\n<div style=\"text-align: left;\"><span style=\"font-family: arial, helvetica, sans-serif;\">Nằm ngủ quay đầu ra cửa sổ tức là kê đầu giường hoặc gối nằm hướng trực tiếp về phía cửa sổ. Đây là một cách sắp xếp giường ngủ khá phổ biến của nhiều gia đình, xuất phát từ thói quen hoặc sở thích cá nhân. Có rất nhiều người thắc mắc liệu nằm ngủ quay đầu ra cửa sổ có tốt không? Sau đây là một số quan điểm về vấn đề này:</span></div>\n<p><br><span style=\"font-family: arial, helvetica, sans-serif;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752787272/SonaSpace/News/Content/rsnf4hsjxtmim2foheja.jpg\" width=\"613\" height=\"613\"></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt;\"><strong>Theo phong thủy</strong></span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Trong phong thủy, việc kê đầu giường hướng ra phía cửa sổ thường được cho là không tốt. Lý do bởi vì cửa sổ là nơi giao hòa khí trong và ngoài phòng ngủ. Vì vậy khi nằm ngủ như thế, gia chủ thường chịu ảnh hưởng bởi các năng lượng xấu từ bên ngoài.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Ngoài ra đầu giường trong phong thủy được coi là một địa tựa, tạo cảm giác an toàn. Khi nằm quay đầu ra phía cửa sổ, nơi lưu thông năng lượng sẽ tạo cảm giác lo lắng, bất an cho gia chủ.</span></p>\n<h3><span style=\"font-family: arial, helvetica, sans-serif; font-size: 14pt;\">Theo một số quan điểm về mặt khoa học</span></h3>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Các nghiên cứu cho rằng khi nằm ngủ quay đầu ra phía cửa sổ đôi khi giấc ngủ sẽ bị gián đoạn bởi ánh sáng và tiếng ồn ở bên ngoài (nhất là vào buổi sáng). Ngoài ra nếu chúng ta quên đóng cửa sổ trước khi ngủ sẽ dễ làm gió và không khí bên ngoài vào trong phòng ngủ gây ảnh hưởng sức khỏe (đặc biệt là phía đầu).</span></p>\n<h3><span style=\"font-family: arial, helvetica, sans-serif;\">Kết luận: Nằm ngủ quay đầu ra phía cửa sổ có tốt không?</span></h3>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Theo cả hai góc nhìn phong thủy và khoa học, việc kê đầu giường quay ra cửa sổ đều không được khuyến khích. Tư thế này dễ khiến giấc ngủ bị ảnh hưởng, gây cảm giác bất an, dễ mệt mỏi và ảnh hưởng đến sức khỏe lâu dài.</span></p>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><img style=\"display: block; margin-left: auto; margin-right: auto;\" src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752787273/SonaSpace/News/Content/xoveaifftr8kacmp1yzg.jpg\"></span></p>\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em>Vị trí nằm ngủ quay đầu ra cửa sổ có sao không?<br></em></span></p>\n<h2><span style=\"font-family: arial, helvetica, sans-serif;\">Cách hóa giải khi đặt giường quay đầu ra cửa sổ</span></h2>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Tuy nhiên, việc kê giường ngủ cạnh cửa sổ cũng mang lại một số lợi ích nhất định như đón ánh sáng tự nhiên, gần gũi với thiên nhiên và tạo cảm giác thư thái, dễ chịu, tiết kiệm điện năng,.... Nếu bạn vẫn muốn nằm ngủ quay đầu ra phía cửa sổ, bạn có thể tham khảo các mẹo sau đây:</span></p>\n<ul>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Đóng cửa sổ khi ngủ</strong>: Để tránh những luồng gió độc từ bên ngoài thổi vào, đặc biệt khi cửa sổ ở ngay đầu giường, bạn nên đóng cửa sổ lại khi ngủ. Điều này giúp bảo vệ sức khỏe và đảm bảo giấc ngủ ngon.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Kê giường ngủ ở vị trí khác</strong>: Cửa sổ nên được đặt ở hướng Nam hoặc Đông Nam để đón nhận ánh sáng và gió tốt nhất. Tránh đặt cửa sổ ở hướng Tây hoặc Tây Bắc vì sẽ gây nóng bức và ẩm ướt.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Thêm rèm cửa</strong>: Dùng rèm cửa có thể che được ánh sáng chói từ bên ngoài, giúp giấc ngủ không bị gián đoạn. Rèm cửa cũng là một cách trang trí phòng ngủ thêm đẹp mắt. Nếu không thể kê giường ở vị trí khác, đây là giải pháp hữu hiệu giúp bạn khắc phục vấn đề.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Sử dụng vách ngăn</strong>: Đặt một tấm vách ngăn giữa giường ngủ và cửa sổ để hạn chế tác động xấu. Vách ngăn có thể được thiết kế với họa tiết trang trí để tạo điểm nhấn cho phòng ngủ.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Chọn cửa sổ cách âm tốt</strong>: Giảm tiếng ồn từ bên ngoài, đặc biệt nếu phòng ngủ gần đường lớn hoặc khu dân cư ồn ào.</span></p>\n</li>\n</ul>\n<p style=\"text-align: center;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><em><img src=\"https://res.cloudinary.com/dmgrdgvcf/image/upload/v1752787273/SonaSpace/News/Content/mgggi02if5benvwuklzf.jpg\"><br></em></span></p>\n<h2><span style=\"font-family: arial, helvetica, sans-serif;\">Những kiêng kỵ khi kê giường ngủ bạn cần tránh</span></h2>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Việc bố trí nội thất hợp lý có thể tạo ra một không gian tối ưu, góp phần cải thiện chất lượng cuộc sống và đảm bảo sức khỏe lâu dài. Dưới đây là một số điều cần tránh khi bạn sắp xếp vị trí giường ngủ:</span></p>\n<ul>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Tránh kê giường đối diện cửa phòng</strong>: Theo quan niệm phong thủy, phần cơ thể tiếp xúc trực tiếp với cửa ra vào sẽ chịu ảnh hưởng nhiều nhất. Nếu đầu giường hướng về cửa, có thể gây đau đầu và chóng mặt. Trường hợp phần thân đối diện cửa, có khả năng dẫn đến các vấn đề về tiêu hóa.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Không đặt giường đối diện gương soi</strong>: Gương đối diện giường có thể làm gián đoạn giấc ngủ, ảnh hưởng đến sự tỉnh táo và hiệu quả trong công việc cũng như học tập. Nếu cần đặt gương trong phòng, nên chọn vị trí không phản chiếu giường ngủ.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Tránh kê giường đối diện cửa nhà vệ sinh hoặc nhà tắm</strong>: Theo phong thủy giường ngủ, vị trí này có thể khiến người nằm thường xuyên bị đau đầu, giảm hiệu suất lao động và ảnh hưởng đến tài chính gia đình.</span></p>\n</li>\n<li style=\"font-family: arial, helvetica, sans-serif;\">\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Không kê giường đối diện phía sau bàn thờ</strong>: Bàn thờ là nơi trang nghiêm để thờ cúng ông bà, tổ tiên. Việc đặt giường ở phía sau lưng bức tường bàn thờ hoặc đối diện bàn thờ đều không phù hợp.</span></p>\n</li>\n</ul>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Hướng đặt giường ngủ theo lời khuyên của chuyên gia phong thủy:</strong></span></p>\n<ul>\n<li style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Người mệnh Hỏa</strong>: Giường ngủ nên được đặt theo hướng Nam, Đông, hoặc Đông Nam.</span></li>\n<li style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Người mệnh Thủy</strong>: Kê giường ngủ theo hướng Bắc, Tây, hoặc Tây Bắc để thu hút tài lộc, may mắn.</span></li>\n<li style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Người mệnh Kim</strong>: Hướng tốt nhất để kê giường là Tây, Tây Bắc, Tây Nam, hoặc Đông Bắc.</span></li>\n<li style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Người mệnh Thổ</strong>: Giường ngủ nên được kê theo hướng Tây Nam, Đông Bắc hoặc hướng Nam.</span></li>\n<li style=\"font-family: arial, helvetica, sans-serif;\"><span style=\"font-family: arial, helvetica, sans-serif;\"><strong>Người mệnh Mộc</strong>: Hướng Đông, Đông Nam, hoặc Bắc là hướng lý tưởng để đặt giường.</span></li>\n</ul>\n<p><span style=\"font-family: arial, helvetica, sans-serif;\">Tóm lại, việc&nbsp;<strong>nằm ngủ quay đầu ra cửa sổ</strong> có sao không phụ thuộc vào nhiều yếu tố. Điều quan trọng nhất là bạn cần tạo ra một không gian thoải mái, an toàn và phù hợp với nhu cầu cá nhân. Nội Thất MOHO luôn sẵn sàng tư vấn và cung cấp các giải pháp nội thất phòng ngủ, giúp bạn có được không gian nghỉ ngơi lý tưởng. Hãy nhớ rằng, việc bố trí hợp lý không chỉ mang lại giấc ngủ ngon mà còn góp phần nâng cao chất lượng cuộc sống của bạn.</span></p>', 0, 41, 1, '5', '0', 0, '2025-08-20 10:46:03', '2025-07-18 04:21:14', NULL);
INSERT INTO `news` (`news_id`, `news_category_id`, `news_name`, `news_image`, `news_slug`, `news_title`, `news_description`, `news_content`, `news_priority`, `news_view`, `news_status`, `news_author`, `news_comment`, `news_reaction`, `updated_at`, `created_at`, `deleted_at`) VALUES
(51, 3, NULL, 'https://res.cloudinary.com/dmgrdgvcf/image/upload/v1754416564/SonaSpace/News/News/zoomwknizbtmhxacieqx.png', 'thiet-ke-thi-cong-cai-tao-can-ho-cao-cap-vinhomes-ba-son-quan-1', 'Thiết kế thi công cải tạo căn hộ cao cấp Vinhomes Ba Son Quận 1', NULL, '<h2 class=\"page-title\"><span style=\"font-size: 18pt;\">Thiết kế thi công cải tạo căn hộ cao cấp Vinhomes Ba Son Quận 1</span></h2>\n<p><span style=\"font-size: 14pt;\"><span style=\"font-size: 12pt;\">Cải tạo nhà không chỉ là thay đổi diện mạo, mà còn là nâng tầm phong cách sống.</span><br><span style=\"font-size: 12pt;\">Mời bạn theo dõi những bước đầu của hành trình biến đổi không gian sống lý tưởng trong căn hộ cao cấp Vinhomes Ba Son Quận 1 được thực hiện bởi SonaSpace.</span><br>———————</span></p>\n<p><span style=\"font-size: 12pt;\">Loại hình: Căn hộ cao cấp<br>Diện tích: 99m2<br>Công năng hiện trạng: 3 phòng ngủ<br>Vị trí: Vinhomes Ba Son, Quận 1, TP.HCM<br>Nhu cầu: Thiết kế thi công cải tạo chuyển đổi công năng.</span></p>\n<p><span style=\"font-size: 12pt;\">NHỮNG CHÍNH SÁCH GIÚP SONASPACE LUÔN NHẬN ĐƯỢC SỰ TIN TƯỞNG VÀ HÀI LÒNG TỪ KHÁCH HÀNG:<br>Làm việc có quy trình, rõ ràng ngay từ đầu.<br>Kiến trúc sư, Nhà thiết kế nội thất có năng lực, tận tâm yêu nghề và am hiểu cả thi công.<br>Đội ngũ thi công trách nhiệm cao, có chuyên môn.<br>Thiết kế hài hòa công năng – thẩm mỹ, khả thi – thi công bám sát thiết kế, đạt chất lượng hoàn thiện tốt.<br>Giá cả hợp lý, tối ưu theo từng điều kiện tài chính của chủ đầu tư.<br>Đảm bảo tiến độ hoàn thành khẩn trương nhanh chóng.<br><br><iframe src=\"https://www.youtube.com/embed/o1QEXpaT2d8\" frameborder=\"0\" style=\"display: table; margin-left: auto; margin-right: auto;\" width=\"560\" height=\"315\" allowfullscreen=\"allowfullscreen\"></iframe></span></p>\n<h2>Thiết kế cải tạo</h2>\n<p><strong>Đường nét – Hình khối</strong></p>\n<p>Tạo ra các đường dẫn thị giác rõ ràng, dù vẫn giữ sự tách biệt từng khu vực trong không gian chung.<br>Đường cong tạo cảm giác mềm mại kết hợp với hình khối giúp tạo sự chuyển tiếp tinh tế, không gian không bị rời rạc mà có sự liên kết hài hòa tự nhiên mà không bị rườm rà.<br>Tạo chiều sâu thị giác thông qua các lớp bố trí chi tiết nội thất trong không gian.<br>Khu vực tủ giày được thiết kế vách gỗ tận dụng diện tích để đáp ứng tối ưu nhu cầu sử dụng mà vẫn tạo được tính thẩm mỹ .<br>Khu thờ đặt liền kề bếp và tủ giày, cùng chung hệ vách nhưng vẫn giữ sự tách biệt rõ ràng để tạo cảm giác trang nghiêm, tôn kính.<br>Thiết kế âm và máy lạnh âm trần kín đáo, hòa vào trần, không gây rối mắt tạo cảm giác trần cao và thoáng.</p>\n<p><strong>Vật liệu – Chất liệu cao cấp và tự nhiên</strong></p>\n<p>Chân bàn ăn: Sử dụng đá sa thạch mang vẻ thô mộc, gần gũi với thiên nhiên.<br>Mặt bàn ăn, chân ghế ăn và bàn trà: Là gỗ sồi tự nhiên cắt lát, giữ nguyên vân gỗ chân thật, tạo sự mộc mạc, ấm áp.<br>Ghế bọc da Ý: Kết hợp vật liệu tự nhiên và thủ công cao cấp, mang nét sang trọng.<br>Sơn hiệu ứng toàn nhà: Không sử dụng sơn thường, mà là sơn hiệu ứng tạo bề mặt nhám, mờ nhẹ, mang lại cảm giác bức tường “thở” theo thời gian, đậm chất Wabi Sabi.</p>\n<p><strong>Ánh sáng – Cảm xúc và chiều sâu</strong></p>\n<p>Tận dụng ánh sáng tự nhiên tối đa, phối hợp với vật liệu tự nhiên như gỗ, đá, cây xanh để tạo không gian vừa gần gũi vừa thư thái.<br>Ánh sáng được bố trí gián tiếp qua hệ thống đèn hắt âm trần, gầm tủ giúp tạo các lớp sáng dịu nhẹ, sâu lắng, đồng điệu với ánh sáng tự nhiên.</p>\n<p><strong>Tinh thần Wabi Sabi và Thiền trong thiết kế</strong></p>\n<p>Không gian tĩnh lặng, tạo cảm giác nhẹ nhàng, hạn chế đồ đạc rườm rà, tạo “chỗ thở” cho con người trong cuộc sống hiện đại.<br>Vật liệu thô mộc, không bóng bẩy – chấp nhận sự “không hoàn hảo” như đặc trưng của Wabi Sabi.<br>Các chi tiết bo tròn, đường cong mềm mại giúp làm dịu cảm xúc, tạo sự ôn hòa, cân bằng.<br>Ánh sáng dịu nhẹ, không chói gắt giúp tâm trí người dùng hướng về trạng thái an yên, tĩnh lặng.</p>\n<p><img class=\"aligncenter wp-image-59819 size-full entered lazyloaded\" title=\"Thiết kế cải tạo căn hộ chung cư Vinhomes Ba Son Quận 1\" src=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4.jpg\" sizes=\"(max-width: 900px) 100vw, 900px\" srcset=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4.jpg 900w, https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4-768x960.jpg 768w\" alt=\"Thiết kế cải tạo căn hộ chung cư Vinhomes Ba Son Quận 1\" width=\"900\" height=\"1125\" data-lazy-srcset=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4.jpg 900w, https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4-768x960.jpg 768w\" data-lazy-sizes=\"(max-width: 900px) 100vw, 900px\" data-lazy-src=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-can-ho-chung-cu-vinhomes-ba-son-quan-1-4.jpg\" data-ll-status=\"loaded\"></p>\n<p><img class=\"aligncenter wp-image-59969 size-full entered lazyloaded\" title=\"Thiết kế cải tạo nội thất căn hộ chung cư Vinhomes Ba Son Quận 1\" src=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-noi-that-can-ho-chung-cu-vinhomes-ba-son-quan-1-2.jpg\" sizes=\"(max-width: 900px) 100vw, 900px\" srcset=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-noi-that-can-ho-chung-cu-vinhomes-ba-son-quan-1-2.jpg 900w, https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-noi-that-can-ho-chung-cu-vinhomes-ba-son-quan-1-2-768x960.jpg 768w\" alt=\"Thiết kế cải tạo nội thất căn hộ chung cư Vinhomes Ba Son Quận 1\" width=\"900\" height=\"1125\" data-lazy-srcset=\"https://ankhoadesign.com.vn/wp-content/uploads/2025/05/thiet-ke-cai-tao-noi-that-can-ho-chung-cu-vinhomes-ba-son-quan-1-2.jpg 900w, https://ankhoadesign.com.vn/